ALTER TABLE users ADD COLUMN security_version BIGINT NOT NULL DEFAULT 1;
ALTER TABLE users ADD COLUMN password_version BIGINT NOT NULL DEFAULT 1;
ALTER TABLE groups ADD COLUMN mfa_required BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE sessions ADD COLUMN authority_epoch BIGINT NOT NULL DEFAULT 0;
ALTER TABLE sessions ADD COLUMN security_version BIGINT NOT NULL DEFAULT 0;
ALTER TABLE sessions ADD COLUMN mfa_at TIMESTAMPTZ NULL;
ALTER TABLE sessions ADD COLUMN last_seen_at TIMESTAMPTZ NULL;
ALTER TABLE sessions ADD COLUMN source_session_id TEXT NOT NULL DEFAULT '';
ALTER TABLE sessions ADD COLUMN gateway_id TEXT NOT NULL DEFAULT '';
ALTER TABLE sessions ADD COLUMN node_id TEXT NOT NULL DEFAULT '';
ALTER TABLE session_profiles ADD COLUMN login_origin TEXT NOT NULL DEFAULT '';
ALTER TABLE session_profiles ADD COLUMN secure_profile BOOLEAN NOT NULL DEFAULT false;
CREATE TABLE security_state (id INTEGER PRIMARY KEY CHECK(id=1), authority_id TEXT NOT NULL, epoch BIGINT NOT NULL, sequence BIGINT NOT NULL, digest TEXT NOT NULL, enabled BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE security_operations (id TEXT PRIMARY KEY, requests_json TEXT NOT NULL, intent_json TEXT NOT NULL, status TEXT NOT NULL, actor_id TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE security_events (sequence BIGINT PRIMARY KEY, event_id TEXT UNIQUE NOT NULL, event_json TEXT NOT NULL);
CREATE TABLE authenticator_floors (principal_id TEXT NOT NULL, authenticator_id TEXT NOT NULL, minimum_version BIGINT NOT NULL, PRIMARY KEY(principal_id,authenticator_id));
CREATE TABLE security_grants (id TEXT PRIMARY KEY, kind TEXT NOT NULL, subject_id TEXT NOT NULL, object_id TEXT NOT NULL, active BOOLEAN NOT NULL DEFAULT true);
CREATE INDEX security_grants_binding ON security_grants(kind,subject_id,object_id);
CREATE TABLE identity_flows (id TEXT PRIMARY KEY, purpose TEXT NOT NULL, audience TEXT NOT NULL, origin TEXT NOT NULL, binding_hash TEXT UNIQUE NOT NULL, csrf_hash TEXT NOT NULL, principal_id TEXT NOT NULL DEFAULT '', security_version BIGINT NOT NULL DEFAULT 0, password_version BIGINT NOT NULL DEFAULT 0, epoch BIGINT NOT NULL, state TEXT NOT NULL, next_step TEXT NOT NULL, primary_verified BOOLEAN NOT NULL DEFAULT false, mfa_verified BOOLEAN NOT NULL DEFAULT false, source_session_id TEXT NOT NULL DEFAULT '', expires_at TIMESTAMPTZ NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, mfa_at TIMESTAMPTZ NULL, recovery_authorized BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE mfa_factors (principal_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, authenticator_id TEXT NOT NULL UNIQUE, version BIGINT NOT NULL, ciphertext TEXT NOT NULL, key_id TEXT NOT NULL, nonce TEXT NOT NULL, last_step BIGINT NOT NULL DEFAULT -1, verified BOOLEAN NOT NULL DEFAULT false, revoked BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE mfa_enrollments (id TEXT PRIMARY KEY, flow_id TEXT NOT NULL UNIQUE REFERENCES identity_flows(id) ON DELETE CASCADE, principal_id TEXT NOT NULL, version BIGINT NOT NULL, ciphertext TEXT NOT NULL, key_id TEXT NOT NULL, nonce TEXT NOT NULL, expires_at TIMESTAMPTZ NOT NULL);
CREATE TABLE recovery_codes (code_hash TEXT PRIMARY KEY, principal_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, batch_version BIGINT NOT NULL, epoch BIGINT NOT NULL, consumed_at TIMESTAMPTZ NULL);
CREATE TABLE identity_limits (bucket TEXT PRIMARY KEY, window_start TIMESTAMPTZ NOT NULL, attempts INTEGER NOT NULL);
CREATE TABLE gateways (id TEXT PRIMARY KEY, node_id TEXT NOT NULL, origin TEXT NOT NULL, callback TEXT NOT NULL, resource_id TEXT NOT NULL REFERENCES resources(id) ON DELETE CASCADE, generation TEXT NOT NULL, enabled BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE handoffs (code_hash TEXT PRIMARY KEY, gateway_id TEXT NOT NULL REFERENCES gateways(id) ON DELETE CASCADE, node_id TEXT NOT NULL, redirect_uri TEXT NOT NULL, challenge TEXT NOT NULL, source_session_id TEXT NOT NULL, principal_id TEXT NOT NULL, security_version BIGINT NOT NULL, epoch BIGINT NOT NULL, expires_at TIMESTAMPTZ NOT NULL, consumed_at TIMESTAMPTZ NULL);
ALTER TABLE sessions DROP CONSTRAINT sessions_audience_check;
ALTER TABLE sessions ADD CHECK (audience IN ('legacy','management','login','gateway'));
